from client.retry import with_backoff


def test_gives_up_after_max_attempts():
    calls = []

    def flaky(timeout=None):
        calls.append(timeout)
        raise OSError("connection reset")

    try:
        with_backoff(flaky, attempts=2, sleep=lambda _: None)
    except OSError:
        pass
    assert len(calls) == 2

import time

MAX_ATTEMPTS = 4
REQUEST_TIMEOUT = 5.0
RETRY_BUDGET = 30.0
BACKOFF_BASE = 0.2


def with_backoff(call, attempts=MAX_ATTEMPTS, budget=RETRY_BUDGET, sleep=time.sleep):
    delay = BACKOFF_BASE
    started = time.monotonic()
    for attempt in range(attempts):
        if time.monotonic() - started > budget:
            raise TimeoutError("retry budget exhausted")
        try:
            return call(timeout=REQUEST_TIMEOUT)
        except OSError:
            if attempt == attempts - 1:
                raise
            sleep(delay)
            delay *= 2
